// React + Tailwind CSS Implementation
import React, { useRef } from "react";

export const SpotlightCard = ({ title, desc, icon }) => {
  const cardRef = useRef(null);

  const handleMouseMove = (e) => {
    if (!cardRef.current) return;
    const rect = cardRef.current.getBoundingClientRect();
    cardRef.current.style.setProperty("--x", `${e.clientX - rect.left}px`);
    cardRef.current.style.setProperty("--y", `${e.clientY - rect.top}px`);
  };

  return (
    <div
      ref={cardRef}
      onMouseMove={handleMouseMove}
      className="relative overflow-hidden rounded-2xl border border-neutral-800 bg-neutral-900/80 p-6 shadow-2xl transition-colors hover:border-orange-500/50 before:pointer-events-none before:absolute before:inset-0 before:bg-[radial-gradient(400px_circle_at_var(--x,-500px)_var(--y,-500px),rgba(255,126,103,0.18),transparent_80%)]"
