// React Scramble Text Component
import React, { useState } from "react";

export const TextScramble = ({ text = "SANGAR CREATIVE ENGINE" }) => {
  const [displayText, setDisplayText] = useState(text);
  const chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%^&*";

  const scramble = () => {
    let iteration = 0;
    const interval = setInterval(() => {
      setDisplayText(text.split("").map((char, index) => {
        if (index < iteration) return text[index];
        return chars[Math.floor(Math.random() * chars.length)];
      }).join(""));
      if (iteration >= text.length) clearInterval(interval);
      iteration += 1 / 3;
    }, 30);
  };

  return (
    <span onMouseEnter={scramble} className="font-mono font-bold tracking-wider cursor-pointer text-orange-400">
      {displayText}
    </span>
  );
};

// React + Framer Motion Magnetic Button
import React, { useRef, useState } from "react";
import { motion } from "framer-motion";

export const MagneticButton = ({ children = "Descubrir Recursos ↗" }) => {
  const ref = useRef(null);
  const [position, setPosition] = useState({ x: 0, y: 0 });

  const handleMouseMove = (e) => {
    const { clientX, clientY } = e;
    const { left, top, width, height } = ref.current.getBoundingClientRect();
    const middleX = clientX - (left + width / 2);
    const middleY = clientY - (top + height / 2);
    setPosition({ x: middleX * 0.35, y: middleY * 0.35 });
  };

  const reset = () => setPosition({ x: 0, y: 0 });

  return (
    <motion.button
      ref={ref}
      onMouseMove={handleMouseMove}
      onMouseLeave={reset}
      animate={{ x: position.x, y: position.y }}
      transition={{ type: "spring", stiffness: 200, damping: 15, mass: 0.1 }}
      className="rounded-full bg-gradient-to-r from-orange-500 to-rose-600 px-8 py-3.5 font-semibold text-white shadow-lg hover:shadow-orange-500/25"
    >
      {children}
    </motion.button>
  );
};

