// React 3D Tilt Component
import React, { useRef } from "react";

export const TiltCard = ({ title = "Vision Pro Glass", children }) => {
  const ref = useRef(null);
  const onMouseMove = (e) => {
    const rect = ref.current.getBoundingClientRect();
    const x = e.clientX - rect.left - rect.width / 2;
    const y = e.clientY - rect.top - rect.height / 2;
    ref.current.style.transform = `perspective(1000px) rotateX(${-y / 10}deg) rotateY(${x / 10}deg) scale3d(1.02, 1.02, 1.02)`;
  };
  const onMouseLeave = () => {
    ref.current.style.transform = "perspective(1000px) rotateX(0deg) rotateY(0deg) scale3d(1, 1, 1)";
  };
  return (
    <div
      ref={ref}
      onMouseMove={onMouseMove}
      onMouseLeave={onMouseLeave}
      className="rounded-2xl border border-neutral-800 bg-neutral-900/90 p-6 transition-transform duration-100 ease-out shadow-2xl backdrop-blur-md"
    >
      <h3 className="text-lg font-bold text-white">{title}</h3>
      {children}
    </div>
  );
};

